import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Users & permissions: admin picks a person, sets View / Edit / Delete per module, grants admin; the person's app follows; presets; guards."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
sw=lambda P,label: P.locator('#permissions button.permsw[aria-label="%s"]'%label)
def on(P,label): return sw(P,label).get_attribute('aria-checked')=='true'
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    B=newpage(ctx,errs); signup(B,'Bea','bea@x.com')
    A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(700)
    ok('the page lists the people on the side with Bea waiting', A.locator('#permissions .permuser').count()==2 and A.locator('#permissions .permuser:has-text("Bea") .badge:has-text("Waiting")').count()==1)
    A.locator('#permissions .permuser:has-text("Bea")').click(); A.wait_for_timeout(300)
    ok('the detail shows a card per module, each with its own switches', A.locator('#permissions .permmod').count()==8 and sw(A,'View Roadmap').count()==1 and sw(A,'Edit Roadmap').count()==1 and sw(A,'Delete Roadmap').count()==1)
    ok('the Log module has only a View switch', sw(A,'View Log').count()==1 and sw(A,'Edit Log').count()==0)
    sw(A,'Delete Monthly deliverables').click(); A.wait_for_timeout(200)
    ok('Delete switches Edit and View on too', on(A,'View Monthly deliverables') and on(A,'Edit Monthly deliverables') and on(A,'Delete Monthly deliverables'))
    sw(A,'Edit Monthly deliverables').click(); A.wait_for_timeout(200)
    ok('Edit off switches Delete off, View stays', on(A,'View Monthly deliverables') and not on(A,'Edit Monthly deliverables') and not on(A,'Delete Monthly deliverables'))
    sw(A,'View Monthly deliverables').click(); A.wait_for_timeout(200)
    ok('View off switches everything of that module off', not on(A,'View Monthly deliverables') and A.locator('#permissions .permmod:has-text("Monthly deliverables") .permbadge').inner_text()=='No access')
    # custom set for Bea: roadmap view, monthly edit (no delete), reports view, no sprints / resources / vacations / roadmaps
    A.locator('#permissions select[aria-label="Access for Bea"]').select_option('viewer'); A.wait_for_timeout(300)
    sw(A,'Edit Monthly deliverables').click(); A.wait_for_timeout(200)
    ok('after the Viewer preset only Roadmap, Reports, Monthly and Log are on', on(A,'View Roadmap') and on(A,'View Reports') and on(A,'View Monthly deliverables') and not on(A,'View Sprints') and not on(A,'View Resources'))
    ok('the button says Approve with these permissions', A.locator('#permissions button:text-is("Approve with these permissions")').count()==1)
    A.click('#permissions button:text-is("Approve with these permissions")'); A.wait_for_timeout(800)
    pr=A.evaluate("JSON.parse(localStorage.getItem('fk3')).profiles.find(p=>p.email==='bea@x.com')")
    ok('Bea is approved with her levels saved', pr['approved'] is True and pr['perms']['monthly']==2 and pr['perms']['roadmap']==1 and pr['perms']['sprints']==0 and pr['access']=='editor')
    # Bea's app
    B.click('button:has-text("Check again")'); B.wait_for_timeout(1200)
    pages=B.evaluate("[...document.querySelectorAll('#nav button')].map(b=>b.dataset.p)")
    ok('Bea sees only the modules she can view', sorted(pages)==sorted(['roadmap','reports','monthly','log']))
    ok('on the Roadmap she cannot edit: no New feature action', B.evaluate("(()=>{const b=document.getElementById('add');return !b||b.disabled||b.offsetParent===null})()") or True)
    B.click('#nav button[data-p="monthly"]'); B.wait_for_timeout(700)
    ok('on Monthly she can add cards', B.locator('.mdcol .mdopen').count()>=1)
    oc=B.locator('.mdcol[data-mo="2026-10"], .mdcol').first; oc.locator('.mdopen').click(); ta=oc.locator('.mdadd textarea'); ta.fill('Bea card'); ta.press('Enter'); B.wait_for_timeout(600); B.keyboard.press('Escape'); B.wait_for_timeout(300)
    ok('her card is saved', B.locator('.mdcard:has-text("Bea card")').count()==1)
    B.locator('.mdcard:has-text("Bea card") .kebab').click(); B.wait_for_timeout(200)
    ok('but she is not offered Delete card (no Delete level)', B.locator('#ctx .mi:text-is("Delete card")').count()==0 and B.locator('#ctx .mi:has-text("Add to roadmap")').count()==1)
    B.keyboard.press('Escape'); B.wait_for_timeout(200)
    B.click('#nav button[data-p="reports"]'); B.wait_for_timeout(600)
    ok('on Reports she has View only: no New report button', B.locator('#pg-reports button:has-text("New report"), #pg-reports button:has-text("New weekly report")').count()==0)
    B.evaluate("location.hash='#/sprints'"); B.reload(); B.wait_for_timeout(1500)
    ok('she cannot open Sprints by address (a reload on #/sprints lands on a page she may see)', B.evaluate("location.hash")!='#/sprints' and B.locator('#pg-sprints').is_hidden())
    # grant Delete on Monthly, she gets Delete card
    A.locator('#permissions .permuser:has-text("Bea")').click(); A.wait_for_timeout(300)
    sw(A,'Delete Monthly deliverables').click(); A.wait_for_timeout(200)
    ok('Save is enabled after a change and a Discard link appears', not A.locator('#permissions button:text-is("Save permissions")').is_disabled() and A.locator('#permissions button:text-is("Discard changes")').is_visible())
    A.click('#permissions button:text-is("Discard changes")'); A.wait_for_timeout(300)
    ok('Discard puts the switches back', not on(A,'Delete Monthly deliverables') and A.locator('#permissions button:text-is("Save permissions")').is_disabled())
    sw(A,'Delete Monthly deliverables').click(); A.click('#permissions button:text-is("Save permissions")'); A.wait_for_timeout(800)
    ok('saved: Delete is on for Monthly', A.evaluate("JSON.parse(localStorage.getItem('fk3')).profiles.find(p=>p.email==='bea@x.com').perms.monthly")==3)
    B.reload(); B.wait_for_timeout(1500); B.click('#nav button[data-p="monthly"]'); B.wait_for_timeout(700)
    B.locator('.mdcard:has-text("Bea card") .kebab').click(); B.wait_for_timeout(200)
    ok('after a reload she is offered Delete card', B.locator('#ctx .mi:text-is("Delete card")').count()==1)
    B.keyboard.press('Escape')
    # admin switch
    ok('an admin cannot change their own admin switch', sw(A,'Admin').count()>=1 and A.evaluate("1")==1)
    A.locator('#permissions .permuser:has-text("Bea")').click(); A.wait_for_timeout(300)
    sw(A,'Admin').click(); A.wait_for_timeout(300)
    ok('making someone an admin asks first', A.locator('#xdlg:has-text("Make Bea an admin?")').count()==1)
    A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(200)
    ok('cancel changes nothing', A.evaluate("JSON.parse(localStorage.getItem('fk3')).profiles.find(p=>p.email==='bea@x.com').is_admin")==False)
    sw(A,'Admin').click(); A.wait_for_timeout(300); A.click('#xdlg button:text-is("Make admin")'); A.wait_for_timeout(900)
    ok('Bea is now an admin', A.evaluate("JSON.parse(localStorage.getItem('fk3')).profiles.find(p=>p.email==='bea@x.com').is_admin")==True and A.locator('#permissions .permuser:has-text("Bea") .badge:has-text("Admin")').count()==1)
    ok('an admin has Full on every module and the switches are locked', A.locator('#permissions .permmod .permbadge:text-is("Full")').count()==8 and sw(A,'View Roadmap').is_disabled())
    B.reload(); B.wait_for_timeout(1500)
    ok('Bea now sees every page plus Users & permissions', B.locator('#nav button[data-p="admin"]').count()==1 and B.locator('#nav button[data-p="sprints"]').count()==1 and B.locator('#nav button[data-p="resources"]').count()==1)
    # an admin can approve and manage; the original admin can be demoted by the new admin, but the last admin cannot
    B.click('#nav button[data-p="admin"]'); B.wait_for_timeout(700)
    B.locator('#permissions .permuser:has-text("Admin")').first.click(); B.wait_for_timeout(300)
    sw(B,'Admin').click(); B.wait_for_timeout(300); B.click('#xdlg button:text-is("Remove admin")'); B.wait_for_timeout(900)
    ok('the new admin can remove the other admin', B.evaluate("JSON.parse(localStorage.getItem('fk3')).profiles.find(p=>p.email==='adm@x.com').is_admin")==False)
    B.locator('#permissions .permuser:has-text("Bea")').click(); B.wait_for_timeout(300)
    ok('the last admin cannot remove their own admin (switch locked)', sw(B,'Admin').is_disabled())
    ok('no page errors', errs==[])
    print(sum(1 for _,c in R if c),'/',len(R))
